--
-- Table structure for table `package_features`
--

DROP TABLE IF EXISTS `package_features`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `package_features` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `package_id` int unsigned NOT NULL,
  `feature_id` int unsigned NOT NULL,
  `feature_type` enum('None','Base','A la carte') NOT NULL DEFAULT 'None',
  `short_description` text NOT NULL,
  `tags` text NOT NULL,
  `additional_store_price` double(15,3) NOT NULL DEFAULT '0.000',
  `additional_store_cost_price` double(15,3) DEFAULT '0.000',
  `primary_store_price` double(15,3) NOT NULL DEFAULT '0.000',
  `primary_store_cost_price` double(15,3) DEFAULT '0.000',
  `trial_period_days` int NOT NULL DEFAULT '0',
  `video_description` text NOT NULL,
  `full_description` text NOT NULL,
  `images` text,
  `videos` text,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `created_by` int NOT NULL DEFAULT '0',
  `updated_by` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `package_id_feature_id` (`package_id`,`feature_id`) USING BTREE,
  KEY `package_id` (`package_id`) USING BTREE,
  KEY `feature_id` (`feature_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=48194 DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

