DROP TABLE IF EXISTS `sub_package_features`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sub_package_features` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `sub_package_id` int unsigned NOT NULL,
  `feature_id` int unsigned NOT NULL,
  `feature_type` enum('None','Base','A la carte') NOT NULL DEFAULT 'None',
  `primary_store_price` double(15,3) NOT NULL DEFAULT '0.000',
  `additional_store_price` double(15,3) NOT NULL DEFAULT '0.000',
  `trial_period_days` int NOT NULL DEFAULT '0',
  `billing_date` datetime DEFAULT NULL,
  `expiry_date` datetime DEFAULT NULL,
  `purchased_date` datetime DEFAULT NULL,
  `purchased_terms` json DEFAULT NULL,
  `cancel_date` datetime DEFAULT NULL,
  `cancel_terms` json DEFAULT NULL,
  `status` enum('Active','Inactive') DEFAULT 'Active',
  `source_of_purchase` enum('CRM','CPANEL','POS') DEFAULT NULL,
  `source_of_cancellation` enum('CRM','POS') DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `sub_package_id_feature_id` (`sub_package_id`,`feature_id`) USING BTREE,
  KEY `sub_package_id` (`sub_package_id`) USING BTREE,
  KEY `feature_id` (`feature_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3218 DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

