CREATE TABLE `subs` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `customer_id` int NOT NULL,
  `subdomain` varchar(50) NOT NULL,
  `protocol` enum('http','https') NOT NULL DEFAULT 'https',
  `shortname` varchar(50) NOT NULL,
  `database_name` varchar(50) NOT NULL,
  `name` varchar(50) NOT NULL,
  `logo` varchar(255) NOT NULL,
  `cloud_print_logo` varchar(255) DEFAULT NULL,
  `logo_zpl` longtext,
  `site_logo` varchar(255) NOT NULL,
  `favicon_icon` varchar(255) NOT NULL,
  `mobile_logo` varchar(255) NOT NULL,
  `industry_id` int unsigned NOT NULL,
  `package_id` int NOT NULL DEFAULT '0',
  `environment_id` int NOT NULL DEFAULT '0',
  `industry_environment_id` int NOT NULL DEFAULT '0',
  `auth_key` varchar(50) NOT NULL,
  `decimal_value` int unsigned NOT NULL DEFAULT '2',
  `s3_folder` varchar(80) DEFAULT NULL,
  `status` enum('Active','Inactive') NOT NULL DEFAULT 'Active',
  `site_created` enum('Yes','No') NOT NULL DEFAULT 'No',
  `allow_package_upgrade` enum('No','Yes') DEFAULT 'No',
  `permission_based_on` enum('Role','User') NOT NULL DEFAULT 'Role',
  `source_of_creation` enum('cpanel','crm') NOT NULL DEFAULT 'cpanel',
  `default_role` int DEFAULT NULL,
  `is_role_synced` enum('0','1') NOT NULL DEFAULT '0',
  `language_id` int NOT NULL DEFAULT '0',
  `currency_id` int NOT NULL DEFAULT '0',
  `bundle_retail_price` double(15,3) NOT NULL DEFAULT '0.000',
  `billing_frequency` enum('Monthly','Annually') NOT NULL DEFAULT 'Monthly',
  `signup_date` datetime NOT NULL,
  `order_count` decimal(15,3) DEFAULT '0.000',
  `product_count` decimal(15,3) DEFAULT '0.000',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `last_access` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `shortname` (`shortname`),
  UNIQUE KEY `subdomain` (`subdomain`),
  KEY `FK_subs_industries` (`industry_id`),
  KEY `status` (`status`),
  KEY `customer_id` (`customer_id`),
  KEY `environment_id` (`environment_id`),
  KEY `industry_environment_id` (`industry_environment_id`),
  KEY `language_id` (`language_id`),
  KEY `currency_id` (`currency_id`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb3 COMMENT='Master entries for subs';
